import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { vec2 } from 'three/tsl';
import { createText } from '@/text';
import { orbit, depthRotate, dissolveMorph, displacementTransition, parallaxScroll, magneticCursor, particleEmerge, flyThrough, kineticText } from '@/primitives';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Object3D } = ctx.THREE;

  // Root container
  const root = new Group();
  root.name = config.name || 'CollectionCard3';

  // Atlas region (fallback to full texture if missing)
  const atlas = config.atlasRegion || { x: 0, y: 0, width: 512, height: 320 };
  const aspect = atlas.width / atlas.height;

  // Geometry sized to aspect ratio (height = 1 unit)
  const geometry = new PlaneGeometry(aspect, 1);
  geometry.name = 'CardPlane';

  // Basic node material (will receive texture later)
  const material = new MeshBasicNodeMaterial();
  material.name = 'CardMaterial';
  material.transparent = true;
  material.depthWrite = false;

  // Mesh
  const mesh = new Mesh(geometry, material);
  mesh.name = 'CardMesh';
  mesh.position.set(0, 0, 0);
  root.add(mesh);

  // Load texture asynchronously (function must stay sync)
  let texture = null;
  const texPromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texPromise.then((tex) => {
    texture = tex;
    // Apply UV offset/repeat for atlas region (assuming full atlas size equals texture size)
    const texSize = new vec2(tex.image.width, tex.image.height);
    const u0 = atlas.x / texSize.x;
    const v0 = atlas.y / texSize.y;
    const uScale = atlas.width / texSize.x;
    const vScale = atlas.height / texSize.y;
    tex.offset.set(u0, v0);
    tex.repeat.set(uScale, vScale);
    tex.needsUpdate = true;
    material.map = tex;
    material.needsUpdate = true;
  });

  // Billboard handler – aligns plane to camera each frame
  root.userData.handlers = {
    update: (camera) => {
      if (mesh && camera) {
        mesh.quaternion.copy(camera.quaternion);
      }
    },
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();
    // Dispose texture if it was loaded
    if (texture) {
      texture.dispose();
    }
    // Clear handlers
    root.userData.handlers = {};
  };

  // No cinematic primitives for this node (config.cinematicPrimitives may be empty)
  // But we still respect the contract: iterate if present
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const primitive = ctx.primitives[prim.name];
      if (primitive) {
        const instance = primitive(root, prim.params);
        // Store for cleanup
        if (!root.userData._primitiveInstances) root.userData._primitiveInstances = [];
        root.userData._primitiveInstances.push(instance);
        // Attach any event handlers if primitive provides them (optional)
        if (instance.handlers) {
          Object.assign(root.userData.handlers, instance.handlers);
        }
      }
    }
    // Extend cleanup to dispose primitives
    const originalCleanup = root.userData.cleanup;
    root.userData.cleanup = () => {
      originalCleanup();
      if (root.userData._primitiveInstances) {
        for (const inst of root.userData._primitiveInstances) {
          if (inst.cleanup) inst.cleanup();
        }
        root.userData._primitiveInstances = null;
      }
    };
  }

  return root;
}
